def test_render_after_note_off_applies_release_envelope():
    # meridian: unit_id=f5f6aafb5968 requirement=1-4
    voice = _Voice("a", 440.0)
    voice.render(voice._attack_samples + 1)
    voice.note_off()
    start_sample = voice._samples_rendered
    start_phase = voice._phase
    frame_count = 4

    rendered = voice.render(frame_count)

    indices = start_sample + np.arange(frame_count)
    release = np.maximum(0.0, 1.0 - (indices - start_sample) / voice._release_samples)
    expected = (
        np.sin(start_phase + voice._phase_increment * np.arange(frame_count))
        * np.minimum(1.0, indices / voice._attack_samples)
        * release
        * audio_logic._PER_VOICE_AMPLITUDE
    ).astype(np.float32)
    np.testing.assert_allclose(rendered, expected)
