import sys
import types
from unittest.mock import Mock

_fake_sounddevice = types.ModuleType("sounddevice")
_fake_sounddevice.OutputStream = Mock()
sys.modules["sounddevice"] = _fake_sounddevice

import audio_logic
from audio_logic import NoteEngine


def _make_engine(monkeypatch, events):
    stream = Mock()
    monkeypatch.setattr(audio_logic.sd, "OutputStream", Mock(return_value=stream))
    return NoteEngine(on_state_change=lambda key, active: events.append((key, active)))


def test_key_up_with_no_active_or_pending_key_is_a_no_op(monkeypatch):
    # meridian: unit_id=ebf2a81ddbb1 requirement=1-4
    events = []
    engine = _make_engine(monkeypatch, events)

    try:
        result = engine.key_up("a")

        assert result is None
        assert engine._active == {}
        assert engine._pending == []
        assert engine._releasing == []
        assert events == []
    finally:
        engine.close()


def test_key_up_releases_the_only_active_voice_and_emits_off(monkeypatch):
    # meridian: unit_id=ebf2a81ddbb1 requirement=1-4
    events = []
    engine = _make_engine(monkeypatch, events)

    try:
        engine.key_down("a")
        voice = engine._active["a"]
        events.clear()

        result = engine.key_up("a")

        assert result is None
        assert "a" not in engine._active
        assert engine._releasing == [voice]
        assert voice._releasing_since == 0
        assert events == [("a", False)]
    finally:
        engine.close()


def test_key_up_promotes_pending_key_and_removes_key_released_while_waiting(monkeypatch):
    # meridian: unit_id=ebf2a81ddbb1 requirement=1-4
    events = []
    engine = _make_engine(monkeypatch, events)

    try:
        for key in ("a", "s", "d", "f", "g"):
            engine.key_down(key)
        events.clear()

        result = engine.key_up("a")

        assert result is None
        assert set(engine._active) == {"s", "d", "f"}
        assert engine._pending == ["g"]
        assert [voice.key for voice in engine._releasing] == ["a"]
        assert events == [("a", False), ("f", True)]

        result = engine.key_up("g")

        assert result is None
        assert engine._pending == []
        assert events == [("a", False), ("f", True)]
    finally:
        engine.close()


